.pomo {
  position: fixed;
  left: 16px;
  bottom: 16px;
  pointer-events: auto;
  font: 14px/1.3 system-ui, sans-serif;
  background: rgba(20, 20, 24, 0.92);
  color: #f4f4f5;
  border-radius: 10px;
  padding: 10px 12px;
  min-width: 132px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
}
.mode { font-size: 12px; opacity: 0.75; }
.time { font-size: 26px; font-variant-numeric: tabular-nums; margin: 2px 0 8px; }
.row { display: flex; gap: 6px; }
button { font: inherit; padding: 4px 10px; border-radius: 6px; border: 1px solid #52525b; background: #27272a; color: inherit; cursor: pointer; }
button:focus-visible { outline: 2px solid #60a5fa; outline-offset: 2px; }

js:
const WORK = 25 * 60;
const BREAK = 5 * 60;
const el = (s) => canvas.root.querySelector(s);
let mode = 'Work';
let left = WORK;
let timer = null;

const render = () => {
  const m = String(Math.floor(left / 60)).padStart(2, '0');
  const s = String(left % 60).padStart(2, '0');
  el('.time').textContent = m + ':' + s;
  el('.mode').textContent = mode;
  el('.start').textContent = timer ? 'Pause' : 'Start';
};
const tick = () => {
  left -= 1;
  if (left <= 0) {
    mode = mode === 'Work' ? 'Break' : 'Work';
    left = mode === 'Work' ? WORK : BREAK;
  }
  render();
};
el('.start').addEventListener('click', () => {
  if (timer) { clearInterval(timer); timer = null; } else { timer = setInterval(tick, 1000); }
  render();
}, { signal: canvas.signal });
el('.reset').addEventListener('click', () => {
  clearInterval(timer);
  timer = null;
  mode = 'Work';
  left = WORK;
  render();
}, { signal: canvas.signal });
canvas.onDispose(() => clearInterval(timer));
render();
